const EVENODD = new Set(['shorts', 'shortsFilled']);

// Gespiegelt dargestellt (Teilen-Pfeil zeigt nach rechts).
const MIRROR = new Set(['share', 'shareFilled']);

// Kräftiger gezeichnet (Shorts-Teilen-Pfeil ist bei YouTube dick und gefüllt).
const BOLD = new Set(['shareFilled']);

const ALIAS = { gear: 'settings' };

const ATTR = 'aria-hidden="true" focusable="false"';

export function icon(name, cls = '') {
  name = ALIAS[name] || name;
  if (OWN[name]) {
    const rule = EVENODD.has(name) ? ' fill-rule="evenodd"' : '';
    return `<svg class="icon ${cls}" viewBox="0 0 24 24" ${ATTR}><path${rule} d="${OWN[name]}"/></svg>`;
  }
  const d = P[name];
  if (!d) return '';
  const tf = MIRROR.has(name) ? ' transform="matrix(-1 0 0 1 960 0)"' : '';
  const bold = BOLD.has(name) ? ' stroke="currentColor" stroke-width="46" stroke-linejoin="round"' : '';
  return `<svg class="icon ${cls}" viewBox="0 -960 960 960" ${ATTR}><path${tf}${bold} d="${d}"/></svg>`;
}

export const ICON_NAMES = [...new Set([...Object.keys(P), ...Object.keys(OWN), ...Object.keys(ALIAS)])];
